class GpuFluidSolver{
    constructor(simulation){
        this.simulation = simulation;
        this.maxParticles = simulation.MAX_PARTICLES;
        this.texSize = Math.ceil(Math.sqrt(this.maxParticles));
        this.texels = this.texSize * this.texSize;
        this.available = false;
        this.error = "";

        try{
            this.canvas = document.createElement("canvas");
            this.canvas.width = this.texSize;
            this.canvas.height = this.texSize;
            this.gl = this.canvas.getContext("webgl2", {
                alpha: false,
                depth: false,
                stencil: false,
                antialias: false,
                preserveDrawingBuffer: false
            });

            if(!this.gl){
                this.error = "WebGL2 is not available";
                return;
            }

            let gl = this.gl;
            if(!gl.getExtension("EXT_color_buffer_float")){
                this.error = "EXT_color_buffer_float is not available";
                return;
            }

            this.positionsA = this.createFloatTexture();
            this.positionsB = this.createFloatTexture();
            this.velFoamA = this.createFloatTexture();
            this.velFoamB = this.createFloatTexture();
            this.aux = this.createFloatTexture();
            this.pressure = this.createFloatTexture();

            this.forceFbo = this.createFramebuffer([
                this.positionsB,
                this.velFoamB,
                this.aux
            ]);
            this.densityFbo = this.createFramebuffer([this.pressure]);
            this.relaxFbo = this.createFramebuffer([this.positionsB]);
            this.finalFbo = this.createFramebuffer([
                this.positionsB,
                this.velFoamB
            ]);
            this.readFbo = gl.createFramebuffer();

            this.vertexBuffer = gl.createBuffer();
            gl.bindBuffer(gl.ARRAY_BUFFER, this.vertexBuffer);
            gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([
                -1, -1,
                 3, -1,
                -1,  3
            ]), gl.STATIC_DRAW);

            this.forceProgram = this.createProgram(this.vertexShaderSource(), this.forceShaderSource());
            this.densityProgram = this.createProgram(this.vertexShaderSource(), this.densityShaderSource());
            this.relaxProgram = this.createProgram(this.vertexShaderSource(), this.relaxShaderSource());
            this.finalProgram = this.createProgram(this.vertexShaderSource(), this.finalShaderSource());

            this.positionUpload = new Float32Array(this.texels * 4);
            this.velFoamUpload = new Float32Array(this.texels * 4);
            this.positionReadback = new Float32Array(this.texels * 4);
            this.velFoamReadback = new Float32Array(this.texels * 4);
            this.auxReadback = new Float32Array(this.texels * 4);
            this.available = true;
        }catch(error){
            this.available = false;
            this.error = error && error.message ? error.message : String(error);
        }
    }

    isAvailable(){
        return this.available;
    }

    step(dt){
        if(!this.available || this.simulation.particles.length === 0){
            return false;
        }

        let gl = this.gl;
        let count = this.simulation.particles.length;
        this.uploadParticles();

        gl.viewport(0, 0, this.texSize, this.texSize);
        gl.disable(gl.BLEND);
        gl.disable(gl.DEPTH_TEST);
        gl.disable(gl.SCISSOR_TEST);

        this.runForcePass(dt, count);
        this.swapPositionTextures();
        this.swapVelFoamTextures();

        for(let i=0; i<this.simulation.RELAX_ITERS; i++){
            this.runDensityPass(count);
            this.runRelaxPass(dt, count);
            this.swapPositionTextures();
        }

        this.runFinalPass(dt, count);
        this.swapPositionTextures();
        this.swapVelFoamTextures();
        this.downloadParticles(count);
        return true;
    }

    uploadParticles(){
        let ps = this.simulation.particles;
        this.positionUpload.fill(0);
        this.velFoamUpload.fill(0);

        for(let i=0; i<ps.length; i++){
            let p = ps[i];
            let o = i * 4;
            this.positionUpload[o] = p.position.x;
            this.positionUpload[o + 1] = p.position.y;
            this.positionUpload[o + 2] = p.prevPosition.x;
            this.positionUpload[o + 3] = p.prevPosition.y;
            this.velFoamUpload[o] = p.velocity.x;
            this.velFoamUpload[o + 1] = p.velocity.y;
            this.velFoamUpload[o + 2] = p.foam || 0;
            this.velFoamUpload[o + 3] = p.age || 0;
        }

        this.uploadTexture(this.positionsA, this.positionUpload);
        this.uploadTexture(this.velFoamA, this.velFoamUpload);
    }

    downloadParticles(count){
        let gl = this.gl;
        let ps = this.simulation.particles;

        this.readTexture(this.positionsA, this.positionReadback);
        this.readTexture(this.velFoamA, this.velFoamReadback);
        this.readTexture(this.aux, this.auxReadback);

        for(let i=0; i<count; i++){
            let p = ps[i];
            let o = i * 4;
            p.position.x = this.positionReadback[o];
            p.position.y = this.positionReadback[o + 1];
            p.prevPosition.x = this.positionReadback[o + 2];
            p.prevPosition.y = this.positionReadback[o + 3];
            p.velocity.x = this.velFoamReadback[o];
            p.velocity.y = this.velFoamReadback[o + 1];
            p.foam = Math.max(0, Math.min(1, this.velFoamReadback[o + 2]));
            p.age = Math.max(0, this.velFoamReadback[o + 3]);
            p.agitation = Math.max(0, this.auxReadback[o]);
            p.cover = Math.max(0, this.auxReadback[o + 1]);
        }

        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    }

    readTexture(texture, target){
        let gl = this.gl;
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.readFbo);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0);
        gl.readBuffer(gl.COLOR_ATTACHMENT0);
        gl.readPixels(0, 0, this.texSize, this.texSize, gl.RGBA, gl.FLOAT, target);
    }

    runForcePass(dt, count){
        let gl = this.gl;
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.forceFbo);
        gl.drawBuffers([
            gl.COLOR_ATTACHMENT0,
            gl.COLOR_ATTACHMENT1,
            gl.COLOR_ATTACHMENT2
        ]);
        this.useProgram(this.forceProgram);
        this.bindCommonUniforms(this.forceProgram, dt, count);
        this.bindTexture(this.forceProgram, "u_posPrev", this.positionsA, 0);
        this.bindTexture(this.forceProgram, "u_velFoam", this.velFoamA, 1);
        this.draw();
    }

    runDensityPass(count){
        let gl = this.gl;
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.densityFbo);
        gl.drawBuffers([gl.COLOR_ATTACHMENT0]);
        this.useProgram(this.densityProgram);
        this.bindCommonUniforms(this.densityProgram, 0.016, count);
        this.bindTexture(this.densityProgram, "u_posPrev", this.positionsA, 0);
        this.draw();
    }

    runRelaxPass(dt, count){
        let gl = this.gl;
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.relaxFbo);
        gl.drawBuffers([gl.COLOR_ATTACHMENT0]);
        this.useProgram(this.relaxProgram);
        this.bindCommonUniforms(this.relaxProgram, dt, count);
        this.bindTexture(this.relaxProgram, "u_posPrev", this.positionsA, 0);
        this.bindTexture(this.relaxProgram, "u_pressure", this.pressure, 1);
        this.draw();
    }

    runFinalPass(dt, count){
        let gl = this.gl;
        gl.bindFramebuffer(gl.FRAMEBUFFER, this.finalFbo);
        gl.drawBuffers([
            gl.COLOR_ATTACHMENT0,
            gl.COLOR_ATTACHMENT1
        ]);
        this.useProgram(this.finalProgram);
        this.bindCommonUniforms(this.finalProgram, dt, count);
        this.bindTexture(this.finalProgram, "u_posPrev", this.positionsA, 0);
        this.bindTexture(this.finalProgram, "u_velFoam", this.velFoamA, 1);
        this.bindTexture(this.finalProgram, "u_aux", this.aux, 2);
        this.draw();
    }

    bindCommonUniforms(program, dt, count){
        let gl = this.gl;
        let sim = this.simulation;
        let g = sim.glass;
        gl.uniform1i(gl.getUniformLocation(program, "u_count"), count);
        gl.uniform1i(gl.getUniformLocation(program, "u_texSize"), this.texSize);
        gl.uniform1f(gl.getUniformLocation(program, "u_dt"), dt);
        gl.uniform2f(gl.getUniformLocation(program, "u_canvasSize"), canvas.width, canvas.height);
        gl.uniform2f(gl.getUniformLocation(program, "u_gravity"), sim.GRAVITY.x, sim.GRAVITY.y);
        gl.uniform1f(gl.getUniformLocation(program, "u_velocityDamping"), sim.VELOCITY_DAMPING);
        gl.uniform1f(gl.getUniformLocation(program, "u_restDensity"), sim.REST_DENSITY);
        gl.uniform1f(gl.getUniformLocation(program, "u_k"), sim.K);
        gl.uniform1f(gl.getUniformLocation(program, "u_kNear"), sim.K_NEAR);
        gl.uniform1f(gl.getUniformLocation(program, "u_radius"), sim.INTERACTION_RADIUS);
        gl.uniform1f(gl.getUniformLocation(program, "u_sigma"), sim.SIGMA);
        gl.uniform1f(gl.getUniformLocation(program, "u_beta"), sim.BETA);
        gl.uniform1f(gl.getUniformLocation(program, "u_foamThreshold"), sim.FOAM_THRESHOLD);
        gl.uniform1f(gl.getUniformLocation(program, "u_foamGen"), sim.FOAM_GEN);
        gl.uniform1f(gl.getUniformLocation(program, "u_foamDecay"), sim.FOAM_DECAY);
        gl.uniform1f(gl.getUniformLocation(program, "u_foamBuoyancy"), sim.FOAM_BUOYANCY);
        gl.uniform1f(gl.getUniformLocation(program, "u_glassVolumeL"), sim.glassVolL);
        gl.uniform1f(gl.getUniformLocation(program, "u_glassCapacityL"), sim.GLASS_CAPACITY_L);
        gl.uniform2f(gl.getUniformLocation(program, "u_glassCenter"), g.center.x, g.center.y);
        gl.uniform1f(gl.getUniformLocation(program, "u_glassAngle"), g.angle);
        gl.uniform1f(gl.getUniformLocation(program, "u_glassTopWidth"), g.topWidth);
        gl.uniform1f(gl.getUniformLocation(program, "u_glassBottomWidth"), g.bottomWidth);
        gl.uniform1f(gl.getUniformLocation(program, "u_glassHeight"), g.height);
        gl.uniform1f(gl.getUniformLocation(program, "u_glassWall"), g.wall);
    }

    useProgram(program){
        let gl = this.gl;
        gl.useProgram(program);
        let loc = gl.getAttribLocation(program, "a_position");
        gl.bindBuffer(gl.ARRAY_BUFFER, this.vertexBuffer);
        gl.enableVertexAttribArray(loc);
        gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
    }

    draw(){
        this.gl.drawArrays(this.gl.TRIANGLES, 0, 3);
    }

    bindTexture(program, name, texture, unit){
        let gl = this.gl;
        gl.activeTexture(gl.TEXTURE0 + unit);
        gl.bindTexture(gl.TEXTURE_2D, texture);
        gl.uniform1i(gl.getUniformLocation(program, name), unit);
    }

    uploadTexture(texture, data){
        let gl = this.gl;
        gl.bindTexture(gl.TEXTURE_2D, texture);
        gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, this.texSize, this.texSize, gl.RGBA, gl.FLOAT, data);
    }

    swapPositionTextures(){
        let t = this.positionsA;
        this.positionsA = this.positionsB;
        this.positionsB = t;
        this.forceFbo = this.createFramebuffer([
            this.positionsB,
            this.velFoamB,
            this.aux
        ]);
        this.relaxFbo = this.createFramebuffer([this.positionsB]);
        this.finalFbo = this.createFramebuffer([
            this.positionsB,
            this.velFoamB
        ]);
    }

    swapVelFoamTextures(){
        let t = this.velFoamA;
        this.velFoamA = this.velFoamB;
        this.velFoamB = t;
        this.forceFbo = this.createFramebuffer([
            this.positionsB,
            this.velFoamB,
            this.aux
        ]);
        this.finalFbo = this.createFramebuffer([
            this.positionsB,
            this.velFoamB
        ]);
    }

    createFloatTexture(){
        let gl = this.gl;
        let texture = gl.createTexture();
        gl.bindTexture(gl.TEXTURE_2D, texture);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA32F, this.texSize, this.texSize, 0, gl.RGBA, gl.FLOAT, null);
        return texture;
    }

    createFramebuffer(textures){
        let gl = this.gl;
        let fbo = gl.createFramebuffer();
        gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
        for(let i=0; i<textures.length; i++){
            gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0 + i, gl.TEXTURE_2D, textures[i], 0);
        }
        let status = gl.checkFramebufferStatus(gl.FRAMEBUFFER);
        if(status !== gl.FRAMEBUFFER_COMPLETE){
            throw new Error("GPU framebuffer is incomplete: " + status);
        }
        return fbo;
    }

    createProgram(vertexSource, fragmentSource){
        let gl = this.gl;
        let vs = this.compileShader(gl.VERTEX_SHADER, vertexSource);
        let fs = this.compileShader(gl.FRAGMENT_SHADER, fragmentSource);
        let program = gl.createProgram();
        gl.attachShader(program, vs);
        gl.attachShader(program, fs);
        gl.linkProgram(program);
        if(!gl.getProgramParameter(program, gl.LINK_STATUS)){
            throw new Error(gl.getProgramInfoLog(program));
        }
        return program;
    }

    compileShader(type, source){
        let gl = this.gl;
        let shader = gl.createShader(type);
        gl.shaderSource(shader, source);
        gl.compileShader(shader);
        if(!gl.getShaderParameter(shader, gl.COMPILE_STATUS)){
            throw new Error(gl.getShaderInfoLog(shader));
        }
        return shader;
    }

    vertexShaderSource(){
        return `#version 300 es
            in vec2 a_position;
            void main(){
                gl_Position = vec4(a_position, 0.0, 1.0);
            }
        `;
    }

    shaderHeader(){
        return `#version 300 es
            precision highp float;
            precision highp int;

            #define MAX_PARTICLES ${this.maxParticles}

            uniform int u_count;
            uniform int u_texSize;
            uniform float u_dt;
            uniform vec2 u_canvasSize;
            uniform vec2 u_gravity;
            uniform float u_velocityDamping;
            uniform float u_restDensity;
            uniform float u_k;
            uniform float u_kNear;
            uniform float u_radius;
            uniform float u_sigma;
            uniform float u_beta;
            uniform float u_foamThreshold;
            uniform float u_foamGen;
            uniform float u_foamDecay;
            uniform float u_foamBuoyancy;
            uniform float u_glassVolumeL;
            uniform float u_glassCapacityL;
            uniform vec2 u_glassCenter;
            uniform float u_glassAngle;
            uniform float u_glassTopWidth;
            uniform float u_glassBottomWidth;
            uniform float u_glassHeight;
            uniform float u_glassWall;

            vec2 uvForIndex(int index){
                int y = index / u_texSize;
                int x = index - y * u_texSize;
                return (vec2(float(x), float(y)) + 0.5) / float(u_texSize);
            }

            int currentIndex(){
                ivec2 pixel = ivec2(gl_FragCoord.xy);
                return pixel.y * u_texSize + pixel.x;
            }

            vec2 worldToGlassLocal(vec2 p){
                float c = cos(u_glassAngle);
                float s = sin(u_glassAngle);
                vec2 d = p - u_glassCenter;
                return vec2(d.x * c + d.y * s, -d.x * s + d.y * c);
            }

            vec2 glassLocalToWorld(vec2 p){
                float c = cos(u_glassAngle);
                float s = sin(u_glassAngle);
                return u_glassCenter + vec2(p.x * c - p.y * s, p.x * s + p.y * c);
            }

            float glassInteriorHalfWidth(float localY){
                float y01 = clamp((localY + u_glassHeight * 0.5) / u_glassHeight, 0.0, 1.0);
                float widthAtY = mix(u_glassTopWidth, u_glassBottomWidth, y01);
                return max(10.0, widthAtY * 0.5 - u_glassWall);
            }

            bool insideGlassInterior(vec2 p){
                vec2 local = worldToGlassLocal(p);
                float halfWidth = glassInteriorHalfWidth(local.y);
                return local.x > -halfWidth &&
                    local.x < halfWidth &&
                    local.y > -u_glassHeight * 0.5 &&
                    local.y < u_glassHeight * 0.5 - u_glassWall;
            }
        `;
    }

    forceShaderSource(){
        return `${this.shaderHeader()}
            uniform sampler2D u_posPrev;
            uniform sampler2D u_velFoam;

            layout(location = 0) out vec4 outPosPrev;
            layout(location = 1) out vec4 outVelFoam;
            layout(location = 2) out vec4 outAux;

            void main(){
                int id = currentIndex();
                if(id >= u_count){
                    outPosPrev = vec4(0.0);
                    outVelFoam = vec4(0.0);
                    outAux = vec4(0.0);
                    return;
                }

                vec4 posPrev = texture(u_posPrev, uvForIndex(id));
                vec4 velFoam = texture(u_velFoam, uvForIndex(id));
                vec2 pos = posPrev.xy;
                vec2 vel = velFoam.xy;
                float foam = velFoam.z;
                float agitation = 0.0;
                float cover = 0.0;
                float radius2 = u_radius * u_radius;
                float invRadius = 1.0 / u_radius;

                vel += u_gravity * u_dt;
                if(foam > 0.04 && insideGlassInterior(pos)){
                    vel.y -= u_gravity.y * u_foamBuoyancy * foam * u_dt;
                }

                for(int j=0; j<MAX_PARTICLES; j++){
                    if(j >= u_count){
                        break;
                    }
                    if(j == id){
                        continue;
                    }

                    vec4 otherPosPrev = texture(u_posPrev, uvForIndex(j));
                    vec4 otherVelFoam = texture(u_velFoam, uvForIndex(j));
                    vec2 r = otherPosPrev.xy - pos;
                    float d2 = dot(r, r);
                    if(d2 >= radius2 || d2 < 1e-8){
                        continue;
                    }

                    float dist = sqrt(d2);
                    vec2 n = r / dist;
                    float u = dot(velFoam.xy - otherVelFoam.xy, n);
                    float omq = 1.0 - dist * invRadius;
                    float stir = omq * abs(u);
                    agitation += stir;
                    if(r.y < 0.0){
                        cover += omq;
                    }

                    if(u > 0.0){
                        float impulse = u_dt * omq * (u_sigma * u + u_beta * u * u) * 0.5;
                        vel -= n * impulse;
                    }
                }

                float overflow = max(0.0, (u_glassVolumeL - u_glassCapacityL) / u_glassCapacityL);
                if(insideGlassInterior(pos)){
                    vel *= 0.999;
                    if(overflow > 0.0){
                        vec2 local = worldToGlassLocal(pos);
                        float surfaceBias = max(0.0, 1.0 - (local.y + u_glassHeight * 0.5) / (u_glassHeight * 0.42));
                        vec2 rimOut = normalize(vec2(-0.78, -0.18));
                        vel += rimOut * overflow * surfaceBias * u_dt * 8.0;
                    }
                }

                vec2 predicted = pos + vel * u_dt * u_velocityDamping;
                outPosPrev = vec4(predicted, pos);
                outVelFoam = vec4(vel, foam, velFoam.w);
                outAux = vec4(agitation, cover, 0.0, 0.0);
            }
        `;
    }

    densityShaderSource(){
        return `${this.shaderHeader()}
            uniform sampler2D u_posPrev;
            out vec4 outPressure;

            void main(){
                int id = currentIndex();
                if(id >= u_count){
                    outPressure = vec4(0.0);
                    return;
                }

                vec2 pos = texture(u_posPrev, uvForIndex(id)).xy;
                float density = 0.0;
                float densityNear = 0.0;
                float radius2 = u_radius * u_radius;
                float invRadius = 1.0 / u_radius;

                for(int j=0; j<MAX_PARTICLES; j++){
                    if(j >= u_count){
                        break;
                    }
                    if(j == id){
                        continue;
                    }

                    vec2 other = texture(u_posPrev, uvForIndex(j)).xy;
                    vec2 r = other - pos;
                    float d2 = dot(r, r);
                    if(d2 < radius2){
                        float omq = 1.0 - sqrt(d2) * invRadius;
                        float omq2 = omq * omq;
                        density += omq2;
                        densityNear += omq2 * omq;
                    }
                }

                outPressure = vec4(u_k * (density - u_restDensity), u_kNear * densityNear, density, densityNear);
            }
        `;
    }

    relaxShaderSource(){
        return `${this.shaderHeader()}
            uniform sampler2D u_posPrev;
            uniform sampler2D u_pressure;
            out vec4 outPosPrev;

            void main(){
                int id = currentIndex();
                if(id >= u_count){
                    outPosPrev = vec4(0.0);
                    return;
                }

                vec4 posPrev = texture(u_posPrev, uvForIndex(id));
                vec2 pos = posPrev.xy;
                vec2 delta = vec2(0.0);
                vec2 pressure = texture(u_pressure, uvForIndex(id)).xy;
                float radius2 = u_radius * u_radius;
                float invRadius = 1.0 / u_radius;
                float dt2 = u_dt * u_dt;

                for(int j=0; j<MAX_PARTICLES; j++){
                    if(j >= u_count){
                        break;
                    }
                    if(j == id){
                        continue;
                    }

                    vec2 other = texture(u_posPrev, uvForIndex(j)).xy;
                    vec2 r = other - pos;
                    float d2 = dot(r, r);
                    if(d2 >= radius2 || d2 < 1e-8){
                        continue;
                    }

                    float dist = sqrt(d2);
                    vec2 n = r / dist;
                    vec2 otherPressure = texture(u_pressure, uvForIndex(j)).xy;
                    float omq = 1.0 - dist * invRadius;
                    float p = max(0.0, 0.5 * (pressure.x + otherPressure.x));
                    float pNear = 0.5 * (pressure.y + otherPressure.y);
                    float disp = dt2 * (p * omq + pNear * omq * omq);
                    delta -= n * disp * 0.5;
                }

                outPosPrev = vec4(pos + delta, posPrev.zw);
            }
        `;
    }

    finalShaderSource(){
        return `${this.shaderHeader()}
            uniform sampler2D u_posPrev;
            uniform sampler2D u_velFoam;
            uniform sampler2D u_aux;

            layout(location = 0) out vec4 outPosPrev;
            layout(location = 1) out vec4 outVelFoam;

            vec2 constrainParticle(vec2 pos){
                vec2 local = worldToGlassLocal(pos);
                float top = -u_glassHeight * 0.5;
                float bottom = u_glassHeight * 0.5;
                float innerHalf = glassInteriorHalfWidth(local.y);
                float outerHalf = innerHalf + u_glassWall;

                if(local.y > top && local.y < bottom){
                    float ax = abs(local.x);
                    if(ax > innerHalf && ax < outerHalf){
                        local.x = sign(local.x) * innerHalf;
                        pos = glassLocalToWorld(local);
                    }
                }

                local = worldToGlassLocal(pos);
                innerHalf = glassInteriorHalfWidth(local.y);
                outerHalf = innerHalf + u_glassWall;
                if(local.y > bottom - u_glassWall && local.y < bottom + u_glassWall && abs(local.x) < outerHalf){
                    local.y = bottom - u_glassWall;
                    pos = glassLocalToWorld(local);
                }

                pos.x = clamp(pos.x, 0.0, u_canvasSize.x - 1.0);
                pos.y = max(pos.y, 0.0);
                float tableY = u_glassCenter.y + u_glassHeight * 0.5 + 2.0;
                if(pos.y > tableY && !insideGlassInterior(pos)){
                    pos.y = tableY;
                }
                pos.y = min(pos.y, u_canvasSize.y - 1.0);
                return pos;
            }

            void main(){
                int id = currentIndex();
                if(id >= u_count){
                    outPosPrev = vec4(0.0);
                    outVelFoam = vec4(0.0);
                    return;
                }

                vec4 posPrev = texture(u_posPrev, uvForIndex(id));
                vec4 velFoam = texture(u_velFoam, uvForIndex(id));
                vec4 aux = texture(u_aux, uvForIndex(id));
                vec2 pos = constrainParticle(posPrev.xy);
                vec2 prev = posPrev.zw;
                vec2 velocity = (pos - prev) / max(u_dt, 0.0001);
                float foam = velFoam.z;
                float age = velFoam.w + u_dt;
                bool inGlass = insideGlassInterior(pos);

                float stir = aux.x - u_foamThreshold;
                if(stir > 0.0 && inGlass){
                    foam = min(1.0, foam + stir * u_foamGen * u_dt);
                }

                float decayRate = u_foamDecay * (1.0 + aux.y * aux.y * 0.6);
                if(!inGlass){
                    decayRate += 0.09;
                }
                foam = max(0.0, foam - foam * decayRate * u_dt);

                outPosPrev = vec4(pos, prev);
                outVelFoam = vec4(velocity, foam, age);
            }
        `;
    }
}

